import pulp

# Data
P = [1, 2, 3]
T = [1, 2, 3, 4]
h = 5
pi_late = {1: 20, 2: 20, 3: 10}
r = {1: 2, 2: 4, 3: 3}
H = {t: 15000 for t in T}
d = {
    (1, 1): 1500, (1, 2): 1000, (1, 3): 2000, (1, 4): 1200,
    (2, 1): 1500, (2, 2): 1500, (2, 3): 1200, (2, 4): 1500,
    (3, 1): 1000, (3, 2): 2000, (3, 3): 1500, (3, 4): 2500
}
I0 = {p: 0 for p in P}
Iend = {p: 150 for p in P}
M = 18700

prob = pulp.LpProblem("Production_Planning", pulp.LpMinimize)

# Decision variables
x = pulp.LpVariable.dicts("x", [(p, t) for p in P for t in T], lowBound=0)
I = pulp.LpVariable.dicts("I", [(p, t) for p in P for t in [0] + T], lowBound=0)
y = pulp.LpVariable.dicts("y", [(p, t) for p in P for t in T], lowBound=0)
l = pulp.LpVariable.dicts("l", [(p, t) for p in P for t in T], lowBound=0)
z = pulp.LpVariable.dicts("z", [(p, t) for p in P for t in T], cat=pulp.LpBinary)

# Objective
prob += pulp.lpSum(5 * I[p, t] for p in P for t in T) + pulp.lpSum(pi_late[p] * l[p, t] for p in P for t in T)

# Constraints
# 4.1 Production-time capacity
for t in T:
    prob += pulp.lpSum(r[p] * x[p, t] for p in P) <= H[t]

# 4.2 No production of product 1 in quarter 2
prob += x[1, 2] == 0

# 4.3 Inventory balance
for p in P:
    prob += I[p, 0] == I0[p]
for p in P:
    for t in T:
        prob += I[p, t] == I[p, t-1] + x[p, t] - y[p, t] - l[p, t]

# 4.4 Demand satisfaction
for p in P:
    for t in T:
        prob += y[p, t] + l[p, t] == d[p, t]

# 4.5 Linking late-delivery amount to binary flag
for p in P:
    for t in T:
        prob += l[p, t] <= M * z[p, t]

# 4.6 End-of-horizon inventory requirement
for p in P:
    prob += I[p, 4] >= Iend[p]

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
